/bin/bash -lc "node --input-type=module <<'EOF'
for (const path of ['/blog/1','/blog/11','/blog/999999']) {
 const r = await fetch('http://localhost:3100'+path)
 const body = await r.text()
 console.log(path, r.status, body.length, body.match(/Comments.{0,70}/g)?.slice(0,3), body.match(/<h1["'^>]*>.*?<'"\\/h1>/g)?.slice(0,3), body.includes('404 - Page Not Found'))
}
EOF"

